{
  "title": "Belém, Bairro Alto and a tram",
  "summary": "A slower day that keeps Belém Tower, swaps the rest for local life, a tram ride and a night in Bairro Alto, with vegetarian-friendly meals.",
  "stops": [
    {
      "poi_id": "p1",
      "kind": "activity",
      "must_do_id": "m1",
      "note": "The one thing we keep, because Belém Tower is history with a sea view and a photo begging to be taken."
    },
    {
      "poi_id": "p14",
      "kind": "meal",
      "must_do_id": null,
      "note": "Lunch right by the tower, because warm custard tarts count as vegetarian and as culture."
    },
    {
      "poi_id": "p12",
      "kind": "activity",
      "must_do_id": null,
      "note": "Feira da Ladra for wandering and people-watching, the flea market way to see local life without rushing."
    },
    {
      "poi_id": "p10",
      "kind": "activity",
      "must_do_id": null,
      "note": "Tram 28 rattles through the old streets, a rolling photo spot for the early bird and the night owl alike."
    },
    {
      "poi_id": "p20",
      "kind": "meal",
      "must_do_id": null,
      "note": "Dinner with proper Portuguese flavours and enough vegetarian options to keep the whole crew happy."
    },
    {
      "poi_id": "p11",
      "kind": "activity",
      "must_do_id": null,
      "note": "Bairro Alto after dark, because the night owl asked for a little festa energy and the streets deliver."
    }
  ]
}
